from lib import *
S = SS('l72')
steps = [
    step(".gitattributes 里写 *.conf filter=redact,配置里 filter.redact.clean 和 filter.redact.smudge 各是一个命令(这里 clean 把 password=… 换成 password=<REDACTED>,smudge 原样输出)。git add app.conf 之后:暂存区里的 blob 内容是 password=<REDACTED>(git cat-file -p :app.conf),而工作区里的文件没变,仍是 password=hunter2。add 时 clean 被调用了一次(日志里 clean app.conf)。过滤器的 %f 参数是文件名。blob 里存的是 clean 的输出,不是工作区的原样内容。", t=tl(S(1)), mark=lidx(S(1), 'password=<REDACTED>', 'clean app.conf'), done=lidx(S(1), 'password=hunter2', '工作区里的文件内容'), kv=KV([['clean', 'add 时:工作区 → blob'], ['smudge', 'checkout 时:blob → 工作区'], ['blob', '存的是 clean 的输出'], ['%f', '文件名参数']], ['clean'])),
    step("各命令什么时候触发过滤器:提交之后 stat 没变的 git status(已经等过 racy 窗口)不调用过滤器;改了文件后 git status 调用 clean(要知道新内容的 hash);git diff --stat 也调用 clean(拿工作区文件和暂存区比较);rm 之后 git checkout -- app.conf 调用 smudge,检出的内容是 password=<REDACTED>——真实密码在这次检出里丢了,因为 clean 是有损的,smudge 又无法还原。", t=tl(S(2)), mark=lidx(S(2), 'rm + git checkout', 'password=<REDACTED>'), done=lidx(S(2), '没有调用过滤器', '改了文件后 git status', 'git diff --stat'), kv=KV([['status', 'stat 变了才 clean'], ['diff', 'clean 工作区再比较'], ['checkout', 'smudge'], ['有损的 clean', '真实内容不可恢复']], ['有损的 clean'])),
    step("跳过过滤器看原始内容:git hash-object app.conf(带过滤器,算的是 clean 之后的内容)得到 71ed8d46…;git hash-object --no-filters app.conf(原样内容)得到 93239901…,两者不同。需要和仓库里的 blob 对账时要想清楚 hash 是哪一种。", t=tl(S(3)), mark=lidx(S(3), '71ed8d46', '93239901'), done=lidx(S(3), '--no-filters', '两者不同'), kv=KV([['hash-object <文件>', '先过滤器再算 hash'], ['--no-filters', '原样内容的 hash']], ['--no-filters'])),
    step("过滤器应当互逆:clean 把大小写全转大写、smudge 全转小写。a.txt 写 Hello World,add 之后暂存区是 HELLO WORLD,工作区仍是 Hello World;删掉后 checkout,工作区变成 hello world(smudge 的输出),git status 却是干净的——因为重新 clean 得到 HELLO WORLD,与暂存区一致。要求是 clean(smudge(x)) == x:看 git 是否认为“有改动”只看工作区内容再 clean 后是否等于暂存区。", t=tl(S(4)), mark=lidx(S(4), 'hello world', 'HELLO WORLD'), done=lidx(S(4), 'Hello World', 'clean(smudge(x)) == x'), kv=KV([['要求', 'clean(smudge(x)) == x'], ['检出的内容', 'smudge 的输出,可以和原来不同'], ['status', '重新 clean 后与暂存区比']], ['要求'])),
    step("自定义 merge driver:.gitattributes 里 VERSION merge=maxver,配置 merge.maxver.driver = pick-max %O %A %B %L %P。ours 把 version 从 1 改成 3,theirs 改成 5(同一行,内置文本合并会冲突)。git merge theirs 输出 Auto-merging VERSION 和 Merge made by the 'ort' strategy.,结果 VERSION 是 version=5。driver 被调用时的实际参数:base=version=1 ours=version=3 theirs=version=5 标记长度=7 路径=VERSION——%O、%A、%B 是三个临时文件(基础、ours、theirs),%L 是冲突标记长度,%P 是路径;driver 把结果写进 %A,退出 0 表示成功。", t=tl(S(5)), mark=lidx(S(5), 'driver 被调用: base=version=1 ours=version=3 theirs=version=5', "Merge made by the 'ort' strategy"), done=lidx(S(5), 'version=5', '标记长度=7 路径=VERSION'), kv=KV([['%O %A %B', '基础 / ours / theirs 的临时文件'], ['%L %P', '标记长度 / 路径'], ['退出 0', '成功,结果在 %A'], ['非 0', '视为冲突']], ['%A'])),
    step("内置的 merge 属性对同一个冲突(两边各在末尾加了一行)的处理:默认(text)报 CONFLICT (content),写入 <<<<<<< HEAD 冲突标记;merge=binary 当作二进制文件,输出 warning: Cannot merge binary files: f.txt (HEAD vs. theirs),同样 CONFLICT,但工作区里只留 ours 的版本(共同的一行 + ours 加的);merge=union 不冲突,把两边的新增行都保留(共同的一行、ours 加的、theirs 加的)。", t=tl(S(6)), mark=lidx(S(6), 'merge=binary', 'merge=union'), done=lidx(S(6), 'merge=(默认 text)', 'CONFLICT'), kv=KV([['text(默认)', '冲突标记'], ['binary', '不合并,留 ours,标记冲突'], ['union', '两边的行都保留,不冲突']], ['union'])),
]
A = mkarti('l72', 72, 'Git,clean,smudge,filter,merge driver,gitattributes,真实验证,动画演示',
    '实测 clean/smudge 过滤器:add 时 clean 后存进 blob(工作区不变),checkout 时 smudge;status/diff 在内容或 stat 变化时调用 clean;clean 有损时真实内容会在检出时丢失;hash-object --no-filters 看原样内容;clean(smudge(x)) 必须等于 x;自定义 merge driver 收到 %O %A %B %L %P,退出 0 采用 %A 里的结果;内置 text/binary/union 对同一冲突的处理。',
    '.gitattributes 里的 filter 和 merge 属性可以改变 git 存取与合并文件的方式。这篇用一个脱敏密码的 clean 过滤器和一个取最大版本号的 merge driver,把 clean / smudge 何时触发、为什么要互逆、driver 收到什么参数逐个验证,再对比内置的 binary 与 union。',
    [('clean → blob', 'add 时工作区内容经过 clean 才存成 blob,工作区本身不变'), ('%O %A %B', '自定义 merge driver 的参数:基础、ours、theirs 的临时文件;结果写回 %A'), ('union', '内置 merge=union:冲突的两边新增的行都保留')],
    [('clean 与 smudge', '<p>filter 属性把文件交给两条命令:<code>clean</code> 在 add(和比较)时把工作区内容转成要存进 blob 的内容,<code>smudge</code> 在 checkout 时把 blob 转成工作区内容。blob 里存的是 clean 的输出。</p>'),
     ('触发时机', '<p>stat 没变的 <code>git status</code> 不调用过滤器;内容变了的 status、<code>git diff</code> 会调用 clean;checkout 调用 smudge。</p>'),
     ('有损的 clean', '<p>clean 有损(例如脱敏)时,smudge 无法还原,工作区被检出覆盖后真实内容就丢了;<code>git hash-object --no-filters</code> 可以看不经过滤的 hash,与带过滤器的 hash 不同。</p>'),
     ('互逆', '<p>好的过滤器满足 <code>clean(smudge(x)) == x</code>:检出得到的内容再 clean 后要与暂存区一致,<code>git status</code> 才是干净的。检出的内容本身可以和原来不同(大小写被改变)。</p>'),
     ('merge driver', '<p><code>merge=名字</code> 加 <code>merge.名字.driver</code> 命令:git 把基础、ours、theirs 写成三个临时文件(<code>%O %A %B</code>),还传冲突标记长度 <code>%L</code> 和路径 <code>%P</code>;driver 把结果写回 <code>%A</code>,退出 0 表示成功,非 0 表示冲突。</p>'),
     ('内置属性', '<p>默认文本合并冲突时写标记;<code>merge=binary</code> 不合并,留 ours 并标记冲突;<code>merge=union</code> 把两边的新增行都保留,不冲突。</p>')],
    steps,
    [ENV_I_GIT + '。过滤器与 driver 都是实验目录里的小 shell 脚本(PATH 前面加了该目录);“clean 触发”的次数来自脚本写的日志',
     '没有验证:长期运行的 filter.<名>.process 协议(git-lfs 用的);filter.<名>.required;ident 属性;textconv 与 diff 驱动;merge driver 在多个冲突块或二进制文件上的行为;rebase 与 cherry-pick 时 driver 的调用;大文件下过滤器的性能'],
    'clean/smudge 与 merge driver')
